afterEach(() => { vi.unstubAllGlobals(); adminWorkspace.reset(); });

test('review source mapping rejects duplicate identities, orphan draft slots and forged mutation fields', () => {
  const item = catalogReview();
  expect(reviewDetailSchema.safeParse(item).success).toBe(true);
  const malformed = [
    { ...item, source: { ...item.source, tracks: [item.source.tracks[0], item.source.tracks[0]] } },
    { ...item, source: { ...item.source, tracks: [item.source.tracks[0], { ...item.source.tracks[1], id: item.source.tracks[0].id }] } },
    { ...item, draft: { ...item.draft, tracks: [item.draft.tracks[0], { ...item.draft.tracks[1], slotId: '10000000-0000-4000-8000-000000000003' }] } },
    { ...item, draft: { ...item.draft, album: { ...item.draft.album, visibility: 'hidden' } } },
    { ...item, source: { ...item.source, tracks: [{ ...item.source.tracks[0], mediaUrl: '/api/private/media' }, item.source.tracks[1]] } },
    { ...item, suggestions: [{ ...item.suggestions[0], field: 'credits' }] },
    { ...item, suggestions: [{ ...item.suggestions[1], slotId: '/other/source' }] },
    { ...item, suggestions: [{ ...item.suggestions[0], generation: 2 }] }
  ];
  for (const value of malformed) expect(reviewDetailSchema.safeParse(value).success).toBe(false);
});

test.each(['/Users/synthetic/Music/01.mp3', '..\\01.mp3', 'C:01.mp3', '.', '..', '\ud800.mp3'])('historical naming evidence rejects a device path or unsafe basename: %s', originalFileName => {
  const item = catalogReview(); item.source.tracks[0].originalFileName = originalFileName;
  expect(reviewDetailSchema.safeParse(item).success).toBe(false);
});

test.each([
  [null, '—'],
  [{ year: 2024, month: null, day: null }, '2024'],
  [{ year: 2024, month: 2, day: null }, '2024-02'],
  [{ year: 2024, month: 2, day: 29 }, '2024-02-29']
])('review dates show only their known calendar precision', (value, text) => {
  expect(reviewValueText(value)).toBe(text);
});

test('review suggestions cannot invent folders or attach filename evidence to a slot whose filename is absent, and Disc and Track Numbers need it', () => {
  const item = catalogReview();
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [{ ...item.suggestions[0], source: 'folder' }] }).success).toBe(false);
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [{ ...item.suggestions[1], slotId: slotTwo }] }).success).toBe(false);
  const number = { ...item.suggestions[1], field: 'trackNumber', baseline: 1, value: 3 };
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [{ ...number, source: 'context' }] }).success).toBe(false);
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [{ ...number, slotId: slotTwo, baseline: null }] }).success).toBe(false);
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [number] }).success).toBe(true);
  // A Disc Number needs filename evidence like a Track Number; a label hint may rest on context.
  const disc = { ...number, field: 'discNumber', baseline: null, value: 2 };
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [disc] }).success).toBe(true);
  for (const value of [{ ...disc, source: 'context' }, { ...disc, slotId: slotTwo }]) expect(reviewDetailSchema.safeParse({ ...item, suggestions: [value] }).success).toBe(false);
  const label = { ...item.suggestions[0], field: 'label', baseline: null, value: { name: 'Synthetic Label', musicBrainzId: null } };
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [label] }).success).toBe(true);
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [{ ...label, scope: 'track', slotId }] }).success).toBe(false);
});

test('applied review history rejects unmapped or duplicate paths and incomplete terminal state', () => {
  const item = catalogReview(), field = { scope: 'album' as const, slotId: null, field: 'title' as const };
  const applied = { operationId: '30000000-0000-4000-8000-000000000003', at: '2026-10-02T00:00:00.000Z', fields: [field] };
  expect(reviewDetailSchema.safeParse({ ...item, state: 'applied', applied }).success).toBe(true);
  expect(reviewDetailSchema.safeParse({ ...item, state: 'applied' }).success).toBe(false);
  expect(reviewDetailSchema.safeParse({ ...item, state: 'applied', applied: { ...applied, fields: [field, field] } }).success).toBe(false);
  expect(reviewDetailSchema.safeParse({ ...item, state: 'applied', applied: { ...applied, fields: [{ scope: 'track', slotId: '10000000-0000-4000-8000-000000000003', field: 'title' }] } }).success).toBe(false);
});

test('change selection includes metadata differences only, preserving Artist identity, label, visibility and artwork', () => {
  const item = catalogReview();
  item.draft.album.title = 'Human Album correction';
  item.draft.album.releaseDate = { year: 2024, month: null, day: null };
  item.draft.album.artists = [{ ...item.draft.album.artists[0], name: 'An identity hint is not an Artist mutation', joinPhrase: ' & ' }];
  item.draft.album.label = { name: 'A label is context', musicBrainzId: null };
  item.draft.album.visibility = 'hidden';
  item.draft.tracks[0].title = 'Human Track correction';
  item.draft.tracks[0].discNumber = 2;
  item.draft.tracks[0].trackNumber = 3;
  const changes = reviewChanges(item);
  expect(changes.map(({ scope, slotId, field }) => ({ scope, slotId, field }))).toEqual([
    { scope: 'album', slotId: null, field: 'title' }, { scope: 'album', slotId: null, field: 'releaseDate' },
    { scope: 'track', slotId, field: 'title' }, { scope: 'track', slotId, field: 'discNumber' }, { scope: 'track', slotId, field: 'trackNumber' }
  ]);
  expect(changes[3]).toMatchObject({ baseline: null, value: 2, title: 'Synthetic first track' });
  expect(changes.some(value => ['artists', 'artistName', 'label', 'visibility', 'coverUrl', 'credits', 'albumId'].includes(value.field))).toBe(false);
  expect(item.source.album.title).toBe('Synthetic catalog Album');
});

test('a review created before Disc Numbers were captured offers no Disc Number change', () => {
  const item = legacyCatalogReview();
  expect(reviewDetailSchema.safeParse(item).success).toBe(true);
  item.draft.tracks[0].discNumber = 2; item.draft.tracks[1].discNumber = 3; item.draft.tracks[1].trackNumber = 4;
  expect(reviewChanges(item).map(({ slotId, field }) => [slotId, field])).toEqual([[slotTwo, 'trackNumber']]);
});

test('the review contract is Draft v2 with captured source discs, and an applied Disc Number is a Track field only', () => {
  const item = catalogReview();
  expect(reviewDetailSchema.safeParse({ ...item, draft: { ...item.draft, album: { ...item.draft.album, label: { name: 'Synthetic Label', musicBrainzId: null } } } }).success).toBe(true);
  expect(reviewDetailSchema.safeParse({ ...item, source: { ...item.source, tracks: [{ ...item.source.tracks[0], discNumber: 999 }, item.source.tracks[1]] } }).success).toBe(true);
  // A v1 draft is a response from a server older than this tab, and the strict parse fails into the reload state.
  const { artists: _artists, label: _label, ...v1Album } = item.draft.album;
  expect(reviewDetailSchema.safeParse({ ...item, draft: { album: { ...v1Album, artistName: 'Synthetic catalog Artist' }, tracks: item.draft.tracks.map(({ discNumber: _disc, ...track }) => track) } }).success).toBe(false);
  for (const discNumber of [0, 1000, '1', 1.5]) {
    expect(reviewDetailSchema.safeParse({ ...item, source: { ...item.source, tracks: [{ ...item.source.tracks[0], discNumber }, item.source.tracks[1]] } }).success).toBe(false);
  }
  const artists = { ...item.suggestions[0], field: 'artists', baseline: item.draft.album.artists, value: [{ key: artistEntryKey, name: 'A synthetic hint', role: 'primary', joinPhrase: null, musicBrainzId: null }] };
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [artists] }).success).toBe(true);
  expect(reviewDetailSchema.safeParse({ ...item, suggestions: [{ ...artists, scope: 'track', slotId }] }).success).toBe(false);
  const applied = (fields: unknown[]) => reviewDetailSchema.safeParse({ ...item, state: 'applied', applied: { operationId: '30000000-0000-4000-8000-000000000003', at: '2026-10-02T00:00:00.000Z', fields } }).success;
  expect(applied([{ scope: 'track', slotId, field: 'discNumber' }])).toBe(true);
  expect(applied([{ scope: 'album', slotId: null, field: 'discNumber' }])).toBe(false);
  expect(applied([{ scope: 'track', slotId, field: 'artists' }])).toBe(false);
  expect(applied(Array.from({ length: 303 }, (_, index) => ({ scope: 'track', slotId: `10000000-0000-4000-8000-${String(index).padStart(12, '0')}`, field: 'title' })))).toBe(false);
});

test('a 100-track review shows every applied field: both Album fields and title, Disc Number and Track Number per Track', () => {
  const item = catalogReview();
  item.source.tracks = Array.from({ length: 100 }, (_, index) => ({ slotId: `10000000-0000-4000-8000-${String(index + 1).padStart(12, '0')}`, id: (index + 1).toString(16).padStart(24, '0'),
    revision: item.source.album.revision, title: `Synthetic track ${index + 1}`, discNumber: null, trackNumber: index + 1, originalFileName: null }));
  item.draft.tracks = item.source.tracks.map(({ slotId: value, title, trackNumber }) => ({ slotId: value, title, discNumber: null, trackNumber }));
  item.suggestions = [];
  const fields = [{ scope: 'album', slotId: null, field: 'title' }, { scope: 'album', slotId: null, field: 'releaseDate' },
    ...item.source.tracks.flatMap(track => (['title', 'discNumber', 'trackNumber'] as const).map(field => ({ scope: 'track', slotId: track.slotId, field })))];
  expect(fields).toHaveLength(302);
  const parsed = reviewDetailSchema.safeParse({ ...item, state: 'applied', applied: { operationId: '30000000-0000-4000-8000-000000000003', at: '2026-10-02T00:00:00.000Z', fields } });
  expect(parsed.success).toBe(true);
  expect(parsed.data?.applied?.fields).toHaveLength(302);
});

test('User presentation refuses review reads, and account epoch changes discard an in-flight private review', async () => {
  const pending = deferred<Response>(), fetch = vi.fn(() => pending.promise); vi.stubGlobal('fetch', fetch);
  adminWorkspace.select('user');
  await expect(adminEndpointRequest('/catalog-reviews/private', reviewResponseSchema)).rejects.toThrow();
  expect(fetch).not.toHaveBeenCalled();
  adminWorkspace.select('admin');
  const read = adminEndpointRequest(`/catalog-reviews/${catalogReview().id}`, reviewResponseSchema);
  advanceAccountEpoch();
  adminWorkspace.authorize(captureAccountOperation('bbbbbbbbbbbbbbbbbbbbbbbb'), true, true, undefined, { editing: true, visibility: true });
  adminWorkspace.select('admin'); pending.resolve(reviewJson({ item: catalogReview(), receipt: null }));
  await expect(read).rejects.toMatchObject({ status: 409, code: 'account_viewer_mismatch' });
  expect(fetch).toHaveBeenCalledTimes(1);
});

test('a review captured for metadata lookup carries its expected tracklist and member Artist entries; import drafts never do', () => {
  const item = capturedCatalogReview();
  expect(reviewDetailSchema.safeParse(item).success).toBe(true);
  expect(reviewDetailSchema.safeParse({ ...item, draft: { ...item.draft, album: { ...item.draft.album, expectedTracklist: null } } }).success).toBe(true);
  // A review not captured carries neither key.
  expect(reviewDetailSchema.safeParse(catalogReview()).success).toBe(true);
  expect(importDraftV2Schema.safeParse(item.draft).success).toBe(false);
  expect(importDraftV2Schema.safeParse({ ...item.draft, album: { ...item.draft.album, expectedTracklist: undefined }, tracks: catalogReview().draft.tracks }).success).toBe(false);
  expect(importDraftV2Schema.safeParse(catalogReview().draft).success).toBe(true);
});

test('a malformed expected tracklist or member entry list fails the strict review parse', () => {
  const item = capturedCatalogReview(), [row] = item.draft.album.expectedTracklist!;
  const withRows = (rows: unknown) => ({ ...item, draft: { ...item.draft, album: { ...item.draft.album, expectedTracklist: rows } } });
  const withEntries = (artists: unknown) => ({ ...item, draft: { ...item.draft, tracks: [{ ...item.draft.tracks[0], artists }, item.draft.tracks[1]] } });
  const entry = (index: number) => ({ key: `50000000-0000-4000-8000-${String(index + 10).padStart(12, '0')}`, name: `Synthetic Artist ${index}`, role: 'primary', joinPhrase: null, musicBrainzId: null });
  for (const value of [
    withRows([row, { ...row }]), withRows([]), withRows(Array.from({ length: 101 }, (_, index) => ({ ...row, trackNumber: index + 1 }))),
    withRows([{ ...row, durationMs: 0 }]), withRows([{ ...row, durationMs: 1.5 }]), withRows([{ ...row, title: '' }]), withRows([{ ...row, discNumber: 1000 }]),
    withRows([{ ...row, recordingId: 'synthetic' }]), withRows('rows'),
    withEntries(Array.from({ length: 21 }, (_, index) => entry(index))), withEntries([entry(1), { ...entry(2), key: entry(1).key }]),
    withEntries([{ ...entry(1), credit: 'extra' }]), withEntries(null),
    { ...item, draft: { ...item.draft, tracks: [{ ...item.draft.tracks[0], credits: [] }, item.draft.tracks[1]] } },
    { ...item, draft: { ...item.draft, album: { ...item.draft.album, missingRows: 1 } } }
  ]) expect(reviewDetailSchema.safeParse(value).success).toBe(false);
  expect(reviewDetailSchema.safeParse(withRows(Array.from({ length: 100 }, (_, index) => ({ ...row, trackNumber: index + 1 })))).success).toBe(true);
  expect(reviewDetailSchema.safeParse(withEntries(Array.from({ length: 20 }, (_, index) => entry(index)))).success).toBe(true);
  // Keys are compared exactly, as the server's entry view keeps them: two keys differing only in letter case are two entries.
  const cased = '50000000-0000-4000-8000-0000000000ab';
  expect(reviewDetailSchema.safeParse(withEntries([{ ...entry(1), key: cased.toUpperCase() }, { ...entry(2), key: cased }])).success).toBe(true);
});

test('a review save lists only the changed editable values with their bases, in a fixed order, never Credits, label, visibility or review-only values', () => {
  const base = capturedCatalogReview().draft, draft = structuredClone(base);
  expect(reviewDraftChanges(base, draft)).toEqual([]);
  draft.tracks[1].trackNumber = 4; draft.tracks[0].discNumber = 2; draft.album.releaseDate = { year: 2024, month: 2, day: null }; draft.tracks[0].title = 'Edited first';
  draft.album.artists = []; draft.album.label = { name: 'Synthetic Label', musicBrainzId: null }; draft.album.visibility = 'hidden';
  draft.album.expectedTracklist = null; draft.tracks[0].artists = []; draft.tracks[1].artists = undefined;
  expect(reviewDraftChanges(base, draft)).toEqual([
    { path: 'album.releaseDate', base: null, value: { year: 2024, month: 2, day: null } },
    { path: `tracks.${slotId}.title`, base: 'Synthetic first track', value: 'Edited first' },
    { path: `tracks.${slotId}.discNumber`, base: null, value: 2 },
    { path: `tracks.${slotTwo}.trackNumber`, base: null, value: 4 }
  ]);
  // A value edited back to its base is no change.
  draft.tracks[0].title = base.tracks[0].title; draft.album.title = 'Edited Album';
  expect(reviewDraftChanges(base, draft).map(change => change.path)).toEqual(['album.title', 'album.releaseDate', `tracks.${slotId}.discNumber`, `tracks.${slotTwo}.trackNumber`]);
  expect(reviewDraftChanges(base, structuredClone(base))).toEqual([]);
});
